export async function getListing(id: string): Promise<Listing> {
  const apiUrl = process.env.NEXT_PUBLIC_API_URL;
  if (apiUrl) {
    try {
      const response = await fetch(`${apiUrl}/listings/${encodeURIComponent(id)}`, { next: { revalidate: 60 } });
      if (response.ok) return await response.json() as Listing;
    } catch {
      // Keep the demo page available when the API is not running yet.
    }
  }
  return demoListing;
}
